def permute(nums):
    n = len(nums); res, path, used = [], [], [False] * n
    def backtrack():
        if len(path) == n:
            res.append(path.copy())  # 收集一份拷贝
            return
        for i in range(n):
            if used[i]:
                continue  # 已用，跳过
            used[i] = True; path.append(nums[i])  # 做选择
            backtrack()
            path.pop(); used[i] = False  # 撤销选择
    backtrack()
    return res

def subsets(nums):
    res, path = [], []
    def backtrack(start):
        res.append(path.copy())  # 每个节点都是一个子集
        for i in range(start, len(nums)):
            path.append(nums[i])  # 做选择
            backtrack(i + 1)  # 只向右选
            path.pop()  # 撤销选择
    backtrack(0)
    return res

def permuteUnique(nums):
    nums.sort()  # 排序使相等数字相邻
    n = len(nums); res, path, used = [], [], [False] * n
    def backtrack():
        if len(path) == n:
            res.append(path.copy())  # 收集完整排列
            return
        for i in range(n):
            if used[i] or (i > 0 and nums[i] == nums[i - 1] and not used[i - 1]):
                continue  # 已用或同层重复，剪枝
            used[i] = True; path.append(nums[i])  # 做选择
            backtrack()
            path.pop(); used[i] = False  # 撤销选择
    backtrack()
    return res

def combinationSum(c, target):
    res, path = [], []
    def backtrack(start, rest):
        if rest == 0:
            res.append(path.copy())  # 凑出目标，收集
            return
        for i in range(start, len(c)):
            if c[i] > rest:
                continue  # 剪枝：超出剩余目标
            path.append(c[i])
            backtrack(i, rest - c[i])  # i 不前移，可重复选
            path.pop()
    backtrack(0, target)
    return res

def exist(board, word):
    m, n = len(board), len(board[0])
    def dfs(x, y, k):
        if k == len(word):
            return True  # 整词匹配完成
        if not (0 <= x < m and 0 <= y < n) or board[x][y] != word[k]:
            return False
        board[x][y] = '#'  # 标记已访问
        ok = any(dfs(x + dx, y + dy, k + 1)
                 for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)))
        board[x][y] = word[k]  # 回溯，恢复字符
        return ok
    return any(dfs(i, j, 0) for i in range(m) for j in range(n))

def solveNQueens(n):
    res, path = [], []
    cols, dg1, dg2 = set(), set(), set()  # 列、主对角、副对角
    def backtrack(row):
        if row == n:
            res.append(['.' * c + 'Q' + '.' * (n - c - 1) for c in path])
            return
        for c in range(n):
            if c in cols or row - c in dg1 or row + c in dg2:
                continue  # 冲突剪枝
            cols.add(c); dg1.add(row - c); dg2.add(row + c); path.append(c)
            backtrack(row + 1)
            path.pop(); cols.remove(c); dg1.remove(row - c); dg2.remove(row + c)
    backtrack(0)
    return res
